import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';

test('lifecycle', async () => {
  const h = await createHost();
  assert.equal(await h.book('a'), null);
  assert.equal((await h.lend('a')).ok, false);
  assert.deepEqual(await h.add('a'), { ok: true });
  assert.equal((await h.add('a')).ok, false);
  assert.equal((await h.giveBack('a')).ok, false);
  for (let i = 1; i <= 3; i++) {
    assert.deepEqual(await h.lend('a'), { ok: true });
    assert.equal((await h.lend('a')).ok, false);
    assert.equal((await h.retire('a')).ok, false);
    assert.deepEqual(await h.book('a'), { status: 'lent', loans: i });
    assert.deepEqual(await h.giveBack('a'), { ok: true });
  }
  assert.equal((await h.lend('a')).ok, false);
  assert.deepEqual(await h.book('a'), { status: 'available', loans: 3 });
  assert.deepEqual(await h.retire('a'), { ok: true });
  for (const c of ['add', 'lend', 'giveBack', 'retire'] as const) assert.equal((await h[c]('a')).ok, false);
  assert.deepEqual(await h.book('a'), { status: 'retired', loans: 3 });
});

test('fresh systems are independent', async () => {
  const a = await createHost();
  await a.add('x');
  const b = await createHost();
  assert.equal(await b.book('x'), null);
});

